def count_open(grid):
    count = 0
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == ".":
                count += 1
    return count

def row_sums(grid):
    sums = []
    for row in grid:
        total = 0
        for x in row:
            total += x
        sums.append(total)
    return sums

